def best_streak(days):
    best = current = 0
    for studied in days:
        current = current + 1 if studied else 0
        best = max(best, current)
    return best

def expense_totals(records):
    result = {}
    for category, amount in records:
        result[category] = result.get(category, 0) + amount
    return result

