def leaderboard(rounds):
    totals = {}
    for name, score in rounds:
        totals[name] = totals.get(name, 0) + score
    return sorted(totals.items(), key=lambda pair: (-pair[1], pair[0]))

def action_counts(lines):
    actions = {}
    for line in lines:
        parts = line.split()
        if len(parts) == 2:
            user, action = parts
            actions.setdefault(user, set()).add(action)
    return {user: len(values) for user, values in actions.items()}

tests:
assert action_counts(['anna login', 'anna login', 'anna save', 'ошибка']) == {'anna': 2}
assert action_counts([]) == {}
assert action_counts(['', 'a b c']) == {}
assert action_counts([' a	b ', 'A b', 'a B']) == {'a': 2, 'A': 1}
print('OK')

