def merge_ranges(ranges):
    result = []
    for start, end in sorted(ranges):
        if result and start <= result[-1][1]:
            result[-1] = (result[-1][0], max(result[-1][1], end))
        else:
            result.append((start, end))
    return result

def shortest_route(graph, start, finish):
    queue = [[start]]
    visited = {start}
    for path in queue:
        node = path[-1]
        if node == finish:
            return path
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(path + [neighbor])
    return []

def build_order(deps):
    result = []
    pending = set(deps)
    while pending:
        ready = sorted(name for name in pending if all(dep in result for dep in deps[name]))
        if not ready:
            return None
        result.append(ready[0])
        pending.remove(ready[0])
    return result

def cache_hits(capacity, requests):
    cache = []
    hits = 0
    for key in requests:
        if key in cache:
            hits += 1
            cache.remove(key)
        elif capacity and len(cache) == capacity:
            cache.pop(0)
        if capacity:
            cache.append(key)
    return hits
